    return '>5m'

def fraud_bucket(r):
    p = r * 100
    if p < 7.2: return '<7.2%'
    if p < 7.7: return '7.2%-7.7%'
    if p < 8.3: return '7.7%-8.3%'
    return '>8.3%'

def load_rows(merchant=None):
    out = []
    with open('inputs/payments.csv') as fh:
        for row in csv.DictReader(fh):
            if merchant and row['merchant'] != merchant:
                continue
