            row['_date'] = datetime.date(2023, 1, 1) + datetime.timedelta(days=d - 1)
            row['_amt'] = float(row['eur_amount'])
            row['_credit'] = row['is_credit'] == 'True'
            row['_fraud'] = row['has_fraudulent_dispute'] == 'True'
            row['_domestic'] = row['issuing_country'] == row['acquirer_country']
            out.append(row)
    return out

