    st = collections.defaultdict(lambda: [0.0, 0.0])
    for r in rows:
        k = (r['merchant'], r['_date'].month)
        st[k][0] += r['_amt']
        if r['_fraud']:
            st[k][1] += r['_amt']
    return st

def rule_matches(rule, m, month_ctx, tx):
    """m: merchant profile; month_ctx: dict with vol_bucket, fraud_bucket; tx: transaction row or dict"""
    if rule['card_scheme'] != tx['card_scheme']:
        return False
    at = rule['account_type']
    if at and m['account_type'] not in at:
        return False
    if rule['capture_delay'] is not None:
        if delay_bracket(m['capture_delay']) != rule['capture_delay']:
